module TopModule (
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] s,
    output logic       overflow
);

    logic [8:0] sum_full;

    assign sum_full = {a[7], a} + {b[7], b};
    assign s = sum_full[7:0];

    // Overflow occurs if the sign of the result doesn't match the expected sign of addition of same-sign numbers,
    // or more standard: carry into sign bit != carry out of sign bit.
    // With 9-bit signed addition: sum_full[8] is the sign extension, sum_full[7] is the actual sign bit.
    // Wait, let's check standard overflow for signed 8-bit addition:
    // overflow = (a[7] == b[7]) && (s[7] != a[7])
    assign overflow = (a[7] == b[7]) && (s[7] != a[7]);

endmodule

