module tb_TopModule;
    logic [7:0] a;
    logic [7:0] b;
    logic [7:0] s;
    logic       overflow;

    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    initial begin
        integer i, j;
        reg [8:0] expected_full;
        reg expected_overflow;
        reg [7:0] expected_s;

        // Test exhaustive or key vectors
        // Since 8-bit inputs are 256 * 256 = 65536 combinations, we can test all of them quickly or sample.
        // Let's test all combinations!
        for (i = -128; i < 128; i = i + 1) begin
            for (j = -128; j < 128; j = j + 1) begin
                a = i[7:0];
                b = j[7:0];
                #1;

                expected_full = $signed(a) + $signed(b);
                expected_s = expected_full[7:0];
                // Signed overflow in 8-bit: if expected_full > 127 or < -128
                expected_overflow = (expected_full > 127 || expected_full < -128);

                if (s !== expected_s || overflow !== expected_overflow) begin
                    $display("SELFTEST FAIL: a=%d, b=%d -> s=%d (exp %d), overflow=%b (exp %b)",
                             $signed(a), $signed(b), $signed(s), $signed(expected_s), overflow, expected_overflow);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

